import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const root=process.cwd(),out=path.resolve(process.argv[2]||'.ci-results/protected-pages'),head=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),tracked=execFileSync('git',['ls-files','-z'],{encoding:'utf8'}).split('\0').filter(Boolean),core=['index.html','weather_today.json','weather_week.json','weather_rules.json','tide_today.json','tide_month.json','notices.json','birdmap-user-guide.png'];
const html=fs.readFileSync('index.html','utf8');for(const token of ['function publicationHead(fresh)','function contributorsCurrent()','_publicationStartedMono','data-publication-app','function fieldGuideOnPosition(position,owner,verified)'])assert.ok(html.includes(token),'protective baseline requires '+token);assert.equal(fs.existsSync(out),false,'Output must be new to avoid packaging old assets');fs.mkdirSync(out,{recursive:true});
const selected=tracked.filter(f=>core.includes(f)||/^(share|sites|site|images|assets|css|js)\//.test(f));for(const f of core)assert.ok(selected.includes(f),'missing required runtime asset '+f);const sha=b=>createHash('sha256').update(b).digest('hex'),files={};for(const f of selected){const dest=path.resolve(out,f);assert.ok(dest.startsWith(out+path.sep));fs.mkdirSync(path.dirname(dest),{recursive:true});const b=fs.readFileSync(f);fs.writeFileSync(dest,b);files[f]=sha(b);}fs.writeFileSync(path.join(out,'protected-baseline.json'),JSON.stringify({head,siteDataCount:190,role:'standby protective Pages artifact, not a deployment',files},null,2)+'\n');console.log(JSON.stringify({head,files:selected.length,indexSha256:files['index.html'],out}));
